class Kinepolis {}

class Cinema {
  + town : string
}

class Theatre {
  + capacity : int
}

class Movie {
  + title : string
}

class MovieCopy {
}

class Show {
  + startTime : datetime
  + isPublished : boolean
}

class Reservation {
  + reservationTime : datetime
  + isCancelled : boolean
}

class CreditCard {
  + cardNumber : string
}

class SeatReservation {
  + seatNumber : string
}

class Ticket {
  + seatNumber : string
  + isAnonymous : boolean
}

class Offer {
  + expiryTime : datetime
}

class FreeTicket {
}

Kinepolis "1" *-- "*" Cinema
Cinema "1" *-- "*" Theatre
Cinema "1" *-- "*" MovieCopy
Movie "1" -- "*" MovieCopy
Theatre "1" *-- "*" Show
MovieCopy "1" -- "*" Show
Show "1" -- "*" Reservation
Show "1" -- "*" Ticket
Reservation "1" *-- "0..1" SeatReservation
Reservation "1" -- "1" CreditCard : paid with
Reservation "0..1" -- "0..1" Offer : triggers
Offer "0..1" -- "0..1" SeatReservation : for
Offer "0..1" -- "1" FreeTicket : results in

@enduml

